#include <stdlib.h>
#include <zlib.h>

int pack(const unsigned char *src, size_t src_len, unsigned char **out, size_t *out_len) {
  unsigned char *dst = malloc(src_len);
  if (dst == NULL) return -1;
  uLongf dst_len = src_len;
  int rc = compress(dst, &dst_len, src, src_len);
  if (rc != Z_OK) {
    free(dst);
    return -1;
  }
  *out = dst;
  *out_len = dst_len;
  return 0;
}

