int unpack(const unsigned char *src, size_t src_len, size_t orig_len, unsigned char **out) {
  unsigned char *dst = malloc(orig_len);
  if (dst == NULL) return -1;
  uLongf dst_len;
  int rc = uncompress(dst, &dst_len, src, (uLong)src_len);
  if (rc != Z_OK) {
    free(dst);
    return -1;
  }
  *out = dst;
  return 0;
}
